"use client";

import { Crown, Zap, Smartphone, ArrowUpRight } from "lucide-react";
import { userData } from "@/data/profile";
import { motion } from "framer-motion";

export default function ProfileHero() {
  const progressPercentage = (userData.loyaltyPoints / userData.pointsToNextTier) * 100;

  return (
    <div className="w-full max-w-4xl mx-auto p-4 md:p-8">
      {/* Welcome Text outside the card */}
      <div className="mb-8">
        <h1 className="text-sm font-bold uppercase tracking-[0.3em] text-foreground-muted mb-1">
          Account Dashboard
        </h1>
        <p className="text-3xl md:text-4xl font-black tracking-tighter uppercase">
          Welcome, {userData.name}
        </p>
      </div>

      {/* The "Debit Card" Hero */}
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="relative aspect-[1.58/1] w-full overflow-hidden rounded-[2rem] bg-linear-to-br from-foreground via-foreground/90 to-foreground/80 p-6 md:p-10 text-background shadow-2xl transition-all duration-500 group"
      >
        {/* Decorative "Chip" and Brand Mark */}
        <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] pointer-events-none" />
        
        <div className="relative z-10 flex justify-between items-start h-full flex-col">
          {/* Top Row: Card Chip & Tier */}
          <div className="w-full flex justify-between items-center">
            {/* Holographic Chip Icon */}
            <div className="w-12 h-9 rounded-md bg-linear-to-br from-background/40 to-background/10 border border-background/20 relative">
                <div className="absolute inset-2 border-r border-b border-background/20" />
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs font-black tracking-widest uppercase opacity-80">
                {userData.tierName} Member
              </span>
              <Crown size={20} />
            </div>
          </div>

          {/* Middle Row: "Card Number" (Loyalty Points) */}
          <div className="w-full mt-auto">
            <p className="text-xs font-medium uppercase tracking-[0.2em] opacity-60 mb-2">
              Membership Credits
            </p>
            <div className="flex gap-4 md:gap-8 text-2xl md:text-4xl font-mono tracking-widest font-bold">
               {/* Formatted like 0000 0000 0000 style */}
               <span>{userData.loyaltyPoints.toString().padStart(4, '0')}</span>
               <span className="opacity-40">PTS</span>
               <span className="hidden md:inline opacity-20">XXXX</span>
               <span className="hidden md:inline opacity-20">2026</span>
            </div>
          </div>

          {/* Bottom Row: User Name & Progress Bar */}
          <div className="w-full mt-6 flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="shrink-0">
              <p className="text-[10px] font-medium uppercase tracking-widest opacity-60 mb-1">
                Cardholder
              </p>
              <p className="text-lg font-bold uppercase tracking-tight">
                {userData.name}
              </p>
            </div>

            {/* In-Card Progress Bar */}
            <div className="flex-1 max-w-xs w-full">
              <div className="flex justify-between text-[10px] font-bold uppercase tracking-tighter mb-2">
                <span>Next Tier: {Math.round(progressPercentage)}%</span>
                <span>{userData.pointsToNextTier} Max</span>
              </div>
              <div className="h-1.5 w-full bg-background/20 rounded-full overflow-hidden">
                <motion.div 
                   initial={{ width: 0 }}
                   animate={{ width: `${progressPercentage}%` }}
                   transition={{ duration: 1.5, ease: "easeOut" }}
                   className="h-full bg-background shadow-[0_0_15px_rgba(var(--surface-base),0.5)]"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Glossy Overlay Effect */}
        <div className="absolute -inset-full bg-linear-to-tr from-transparent via-white/10 to-transparent rotate-45 pointer-events-none group-hover:translate-x-1/2 transition-transform duration-1000" />
      </motion.div>

      {/* Sub-Card Benefits (Theme Based) */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
        <BenefitMiniCard icon={<Zap size={16} />} label="Instant Cashback" />
        <BenefitMiniCard icon={<Smartphone size={16} />} label="App Priority" />
        <BenefitMiniCard icon={<ArrowUpRight size={16} />} label="Tier Perks" />
        <div className="flex flex-col items-center justify-center p-4 rounded-2xl border border-dashed border-border text-foreground-muted hover:text-foreground hover:border-foreground transition-colors cursor-pointer">
           <span className="text-[10px] font-bold uppercase tracking-widest">View All Perks</span>
        </div>
      </div>
    </div>
  );
}

function BenefitMiniCard({ icon, label }: { icon: React.ReactNode, label: string }) {
    return (
        <div className="flex flex-col gap-3 p-4 rounded-2xl bg-background-muted border border-border hover:bg-background transition-colors duration-300">
            <div className="text-foreground">{icon}</div>
            <span className="text-[10px] font-bold uppercase tracking-widest text-foreground-muted">{label}</span>
        </div>
    )
}